+  FT_CALLBACK_DEF( FT_Int )
+  tt_cmap_dmap_char_var_isdefault( FT_CMap    cmap,
+                                   FT_UInt32  char_code,
+                                   FT_UInt32  variant_selector )
+  {
+    TT_CMap        ttcmap = (TT_CMap)cmap;
