+
+    if ( clazz->char_var_default )
+      result = clazz->char_var_default( ttcmap->dmap,
+                                        char_code, variant_selector );
+
+    clazz = ttcmap->cmap_class;
+    if ( result == -1 && clazz->char_var_default )
+      result = clazz->char_var_default( cmap, char_code,
+                                        variant_selector );
