+        fit       = FT_BOOL( flags & FT_GASP_SYMMETRIC_GRIDFIT );
+      }
+    }
+
+    if ( symmetric_smoothing )
+      *symmetric_smoothing = symmetric;
+
+    if ( grid_fit )
+      *grid_fit = fit;
+  }
